/* Replace the inaccurate "Funny" catch-all labels with readable topics.
   Every card must still use a published filter category. */
function topicLabel(question,game){
 const q=String(question||'').toLowerCase();
 const funny=/cat|dog|parrot|goat|robot|fridge|kettle|biscuit|pizza|sock|coffee machine|ridiculous|absurd|silly|funny|strange|nonsense|superhero|dramatic|overcomplicat|wrong group|toaster|singing|dancing|pigeon|kitchen disaster|impossible|accidentally|underwear|hat\b|sandwich|cereal|slippers/.test(q);
 const romance=/date\b|dating|romantic|partner|couple|crush|breakup|flirt|relationship|jealous|love life|kiss|boyfriend|girlfriend|chemistry|attraction/.test(q);
 const travel=/travel|holiday|vacation|flight|airport|train|hotel|passport|trip\b|tourist|foreign city|journey|luggage|suitcase/.test(q);
 const work=/work\b|manager|job\b|office|colleague|meeting|deadline|project|employee|client|team\b|presentation|customer|boss|professional|productivity/.test(q);
 const social=/friend|group|argument|debate|conversation|trust|honesty|promise|opinion|decision|choice|rule|question|disagreement|fair|privacy|included|someone|people|stranger|apology|criticism|respect|help|responsibilit|community|conflict|boundary|perspective|uncertain|communication|social|belief/.test(q);
 if(game==='never-have-i-ever'){
  if(romance)return 'Spicy';
  if(travel)return 'Travel';
  if(funny)return 'Funny';
  if(work)return 'Work';
  if(social)return 'Social';
  return 'Everyday';
 }
 if(game==='most-likely-to'){
  if(romance)return 'Spicy';
  if(funny)return 'Funny';
  if(/chaos|accident|lose track|disaster|confusion|wrong place|unexpected|panic/.test(q))return 'Chaos';
  if(/future|in ten years|next year|retirement|in five years/.test(q))return 'Future';
  return 'Social';
 }
 if(game==='last-thing-you-did'){
  if(romance)return 'Spicy';
  if(funny)return 'Funny';
  if(social||/learned|achievement|proud|goal|habit|strength/.test(q))return 'Personal';
  return 'Everyday';
 }
 return null;
}
const everCats=B.categorySets['never-have-i-ever'];
if(!everCats.includes('Everyday'))everCats.unshift('Everyday');
for(const level of levels){
 for(const entry of G['never-have-i-ever'][level])entry[0]=topicLabel(entry[1],'never-have-i-ever');
 for(const entry of G['most-likely-to'][level])entry[0]=['Chaos','Future'].includes(entry[0])?entry[0]:topicLabel(entry[1],'most-likely-to');
 for(const entry of G['last-thing-you-did'][level])entry.c=topicLabel(entry.q,'last-thing-you-did');
 // Ensure all categories are available without adding artificial "fill" cards.
 for(const game of ['never-have-i-ever','most-likely-to','last-thing-you-did']){
  const cats=new Set(B.categorySets[game]);
  const actual=G[game][level].map(x=>x.c||x[0]);
  if(actual.some(cat=>!cats.has(cat)))throw Error('Invalid topic label '+game+'/'+level);
 }
}


