function diversify(game,level,lib){
 const current=G[game][level],easy=level==='A1-A2';
 const legacy=easy?lib.easyIndices.map(i=>lib.legacy[i]):lib.legacy;
 const candidate=[...current.slice(0,30),...(easy?lib.bonus:[]),...legacy,...current.slice(30)];
 const result=[],seen=new Set();
 for(const card of candidate){
  const k=norm(card[1]);if(!k||seen.has(k))continue;
  if(result.length<100){result.push(card);seen.add(k)}
 }
 if(result.length!==100)throw Error('Incorrect debate count '+game+'/'+level+'/'+result.length);
 if(result.some(x=>!B.categorySets[game].includes(x[0])))throw Error('Invalid debate category '+game+'/'+level);
 return result;
}
